<script setup>
import {ref,watch,onMounted,onUnmounted} from 'vue';import {createApi} from '../lib/api.js';import {createChatController,crisisOffer} from '../controllers/chatController.js';
const emit=defineEmits(['choose','conversation','support']);const api=createApi(fetch,25000);const controller=createChatController(api);const input=ref(''),messages=ref([]),loading=ref(false),error=ref(''),health=ref(null),mode=ref(''),offer=ref(false),choices=ref(false);
const props=defineProps({active:Boolean});watch(()=>props.active,active=>{if(!active){controller.invalidate();loading.value=false;}});
async function send(retry=false){if(loading.value)return;offer.value=crisisOffer(input.value);loading.value=true;error.value='';choices.value=false;const outcome=await controller.send(input.value,retry);if(outcome.stale||outcome.ignored)return;loading.value=false;if(outcome.error){error.value=outcome.error.message;return;}const data=outcome.value;emit('conversation',controller.conversationId);mode.value=data.mode;for(const message of data.messages){if(!messages.value.some(m=>m.id===message.id))messages.value.push({...message,mode:data.mode});}if(data.status==='succeeded'){choices.value=true;input.value='';}else error.value=`Chat ${data.status} (${data.error_code||'no response'}). You can still choose either exercise.`;}
function reset(){controller.reset();messages.value=[];error.value='';input.value='';mode.value='';choices.value=false;loading.value=false;offer.value=false;emit('conversation',null);}
onMounted(async()=>{try{health.value=await api('/health');}catch{error.value='Chat status is unavailable. Exercises and support still work.';}});onUnmounted(()=>controller.invalidate());
</script>
<template><section class="chat-card card" aria-label="Optional fictional conversation"><div class="chat-top"><span class="chat-avatar" aria-hidden="true">✳</span><button class="text-button" @click="reset">New conversation</button></div><p>A short conversation can help you choose where to begin.</p><p class="fine">{{!health?'Chat status unavailable':health.mode==='live'?(health.configuration_status==='missing_configuration'?'Live mode · missing configuration':`Live mode · ${health.live_verified?'provider verified':'provider not yet verified'}`):'Mock mode · clearly simulated replies'}} · use fictional scenarios</p><div class="chat-messages" aria-live="polite"><article v-for="message in messages" :key="message.id" :class="message.role"><span class="eyebrow">{{message.role==='user'?'Fictional student':'Campus Pause'}} · {{message.mode}} · {{message.status}}</span><p>{{message.text}}</p></article></div><p v-if="offer" class="support-offer">Support is available independently of this chat. <button class="text-button" @click="emit('support')">Open support resources</button></p><form @submit.prevent="send()"><label class="sr-only" for="chat-input">Optional fictional message</label><textarea id="chat-input" v-model="input" maxlength="500" rows="2" placeholder="Optional fictional message…" :disabled="loading"/><div class="chat-actions"><span class="fine">{{input.length}} / 500 · optional</span><button class="primary small" :disabled="loading||!input.trim()" type="submit">{{loading?'Waiting…':'Send →'}}</button></div></form><p v-if="loading" role="status" class="fine">Waiting for chat. You can begin either exercise now.</p><p v-if="error" class="error" role="alert">{{error}} <button v-if="controller.pending" class="text-button" :disabled="loading" @click="send(true)">Retry same request</button></p><div v-if="choices" class="chat-choices"><button class="secondary small" @click="emit('choose','breathing')">Choose breathing</button><button class="secondary small" @click="emit('choose','grounding')">Choose grounding</button></div></section></template>
